def _vector(api, reader, context):
    vector = api.fields(context["version_vector"],
                        ("schema", "package_version", "spec_files", "source_files", "input_files",
                         "lock_files", "tool_files", "environment", "components"), label="W09 vector")
    api.require(vector["schema"] == "researchos.w09.version-vector.v1"
                and vector["package_version"] == "2.4.0", "SCHEMA", "W09 vector")
    pinned = {}
    for group in ("spec_files", "source_files", "input_files", "lock_files", "tool_files"):
        rows = api.sequence(vector[group], group, False)
        api.require(len(rows) == len({r["path"] for r in rows}), "DUPLICATE_REFERENCE", group)
        for ref in rows:
            try:
                path = reader.ref(ref)
            except api.InvalidEvidence as exc:
                if exc.code in {"HASH_MISMATCH", "FILE_MISSING"}:
                    raise api.InvalidEvidence("NEEDS_REVALIDATION", ref["path"]) from exc
                raise
            api.require(path not in pinned or pinned[path] == ref["sha256"], "VECTOR_CONFLICT", ref["path"])
            pinned[path] = ref["sha256"]
    sources = {r["path"] for r in vector["source_files"]}
    api.require(MINIMUM_SOURCE <= sources, "SOURCE_COVERAGE", "W09 trusted and product sources")
    for directory in ("internal/domain", "adapters/retrieval"):
        required = {p.relative_to(reader.repo).as_posix()
                    for p in (reader.repo / directory).glob("*.go") if p.is_file()}
        api.require(required <= sources, "SOURCE_COVERAGE", directory + " Go source inventory")
    api.coverage(reader, context["source_coverage"], vector["source_files"])
    for name, digest in api.FROZEN_HASHES.items():
        api.require(any(Path(r["path"]).name == name and r["sha256"] == digest
                        for r in vector["spec_files"]), "VECTOR_BASELINE", name)
    for name in ("execution/v2.4/commands.json", "execution/toolchains/locked.json"):
        api.require(reader.path(name) in pinned, "VECTOR_INPUT", name)
    environment = api.fields(vector["environment"], ("os", "arch", "timezone"), label="environment")
    for value in environment.values():
        api.text(value, "environment")
    components = api.fields(vector["components"], ("model", "adapter", "rubric", "policy"), label="components")
    for name, component in components.items():
        api.fields(component, ("status", "reason") if name in {"model", "rubric"} else
                   ("status", "version", "refs"), label=name)
        if name in {"model", "rubric"}:
            api.require(component["status"] == "not_applicable" and api.text(component["reason"], name),
                        "COMPONENT_STATUS", name)
        else:
            api.require(component["status"] == "applicable" and api.text(component["version"], name),
                        "COMPONENT_STATUS", name)
            for ref in api.sequence(component["refs"], name):
                api.require(pinned.get(reader.ref(ref)) == ref["sha256"], "COMPONENT_UNPINNED", name)
    return pinned

class Reader:
    def __init__(self, repo):
        self.repo = Path(repo).resolve(strict=True)
        require(self.repo.is_dir(), "REPO", str(repo))
        self.read_hashes = {}
        self.proof_cache = {}

    def path(self, relative, prefix=None):
        text(relative, "path")
        require("\\" not in relative and "\x00" not in relative, "PATH_FORMAT", relative)
        posix, windows = PurePosixPath(relative), PureWindowsPath(relative)
        require(not posix.is_absolute() and not windows.drive and not windows.root,
                "PATH_ESCAPE", relative)
        require(all(part not in ("", ".", "..") for part in relative.split("/")), "PATH_ESCAPE", relative)
        if prefix:
            require(relative.startswith(prefix), "PATH_SCOPE", relative)
        try:
            resolved = (self.repo / relative).resolve(strict=True)
        except (OSError, RuntimeError) as exc:
            raise InvalidEvidence("FILE_MISSING", relative) from exc
        require(resolved.is_relative_to(self.repo) and resolved.is_file(), "PATH_ESCAPE", relative)
        if prefix:
            boundary = (self.repo / prefix).resolve(strict=True)
            require(resolved.is_relative_to(boundary), "PATH_ESCAPE", relative)
        return resolved

    def supplied(self, path, prefix=None):
        candidate = Path(path)
        if not candidate.is_absolute():
            return self.path(candidate.as_posix(), prefix)
        require(candidate.is_relative_to(self.repo), "PATH_ESCAPE", str(path))
        return self.path(candidate.relative_to(self.repo).as_posix(), prefix)

    def read(self, path):
        raw = Path(path).read_bytes()
        current = hashlib.sha256(raw).hexdigest()
        if path in self.read_hashes:
            require(current == self.read_hashes[path], "INPUT_CHANGED_DURING_READ", str(path))
        self.read_hashes[path] = current
        return strict_json(raw)

    def ref(self, value, prefix=None, locator=False):
        fields(value, ("path", "sha256"), ("locator",) if locator else (), "reference")
        expected = value["sha256"]
        require(type(expected) is str and SHA.fullmatch(expected), "HASH_FORMAT", value["path"])
        path = self.path(value["path"], prefix)
        actual = sha256(path)
        require(actual == expected, "HASH_MISMATCH", value["path"])
        if path in self.read_hashes:
            require(actual == self.read_hashes[path], "INPUT_CHANGED_DURING_READ", value["path"])
        self.read_hashes[path] = actual
        return path

    def document(self, value, prefix=None):
        return self.read(self.ref(value, prefix))

    def raw(self, value):
        path = self.ref(value, PREFIX, locator=True)
        require("locator" in value, "RAW_LOCATOR", value["path"])
        location = obj(value["locator"], "raw locator")
        raw = path.read_bytes()
        if set(location) == {"json_pointer"}:
            pointer = location["json_pointer"]
            require(type(pointer) is str and (pointer == "" or pointer.startswith("/")), "RAW_LOCATOR", str(pointer))
            result = strict_json(raw)
            if pointer:
                for token in pointer[1:].split("/"):
                    require(re.search(r"~(?![01])", token) is None, "RAW_LOCATOR", pointer)
                    token = token.replace("~1", "/").replace("~0", "~")
                    if type(result) is dict:
                        require(token in result, "RAW_LOCATOR_MISSING", pointer)
                        result = result[token]
                    elif type(result) is list:
                        require(re.fullmatch(r"0|[1-9][0-9]*", token) is not None,
                                "RAW_LOCATOR_MISSING", pointer)
                        require(int(token) < len(result), "RAW_LOCATOR_MISSING", pointer)
                        result = result[int(token)]
                    else:
                        raise InvalidEvidence("RAW_LOCATOR_MISSING", pointer)
        elif set(location) == {"line_start", "line_end"}:
            start, end = location["line_start"], location["line_end"]
            require(type(start) is int and type(end) is int, "RAW_LOCATOR", "integer lines")
            try:
                lines = raw.decode("utf-8").splitlines()
            except UnicodeError as exc:
                raise InvalidEvidence("RAW_ENCODING", value["path"]) from exc
            require(1 <= start <= end <= len(lines), "RAW_LOCATOR_MISSING", value["path"])
            result = "\n".join(lines[start - 1:end])
        else:
            raise InvalidEvidence("RAW_LOCATOR", "expected JSON pointer or inclusive line range")
        require(meaningful(result), "RAW_EMPTY", value["path"])
        return result

    def finish(self):
        for path, digest in self.read_hashes.items():
            require(path.is_file() and sha256(path) == digest, "INPUT_CHANGED_DURING_READ", str(path))

    def local_tool(self, path, digest):
        text(path, "tool path")
        windows = PureWindowsPath(path)
        require((Path(path).is_absolute() or windows.is_absolute()) and not windows.drive.startswith("\\\\")
                and not path.startswith("//"), "TOOL_PATH", path)
        require(type(digest) is str and SHA.fullmatch(digest), "HASH_FORMAT", path)
        actual = Path(path).resolve(strict=True)
        require(actual.is_file(), "TOOL_PATH", path)
        if actual not in self.read_hashes:
            self.read_hashes[actual] = sha256(actual)
        require(self.read_hashes[actual] == digest, "TOOL_CHANGED", path)
        return actual

def _canonical_state(reader, state_path, planned):
    path = Path(state_path).resolve(strict=True)
    require(path == (reader.repo / "execution/v2.4/step_state.json").resolve(), "CANONICAL_STATE", str(path))
    state = obj(reader.read(path), "canonical state")
    require(state.get("schema_version") == "1.0" and state.get("package_version") == "2.4.0"
            and state.get("plan_sha256") == FROZEN_HASHES["execution.plan.json"], "STATE_BASELINE", str(path))
    rows = sequence(state.get("steps"), "state steps", False)
    ids = [text(row.get("id"), "state id") for row in rows]
    require(len(ids) == len(set(ids)) and set(ids) <= set(planned), "STATE_IDS", "duplicate or unknown step")
    statuses = {"NOT_STARTED", "IN_PROGRESS", "EXECUTION_REPORTED", "ACCEPTED", "BLOCKED", "FAILED", "CANCELLED"}
    for row in rows:
        require(row.get("status") in statuses, "STATE_STATUS", row["id"])
    return {row["id"]: row for row in rows}

def _registered_roots(reader, owner, task_id):
    selected = {"review": [], "context": [], "issuance": []}
    require(task_id in {"W04", "W07", "W09"}, "UNSUPPORTED_PROTOCOL", task_id)
    protocol = task_id.lower()
    schemas = {"researchos." + protocol + "." + name + ".v1": kind
               for kind, name in (("review", "independent-review"), ("context", "current-context"),
                                  ("issuance", "root-observed-issuance"))}
    seen = set()
    for reference in sequence(owner.get("evidence"), "registered owner evidence"):
        fields(reference, ("path", "sha256"), label="registered reference")
        translated = {"path": "execution/v2.4/" + reference["path"], "sha256": reference["sha256"]}
        path = reader.ref(translated)
        require(path not in seen, "DUPLICATE_REFERENCE", task_id)
        seen.add(path)
        if path.suffix != ".json":
            continue
        value = reader.read(path)
        if type(value) is dict and value.get("schema") in schemas:
            key = schemas[value["schema"]]
            selected[key].append(path)
    require(all(len(values) == 1 for values in selected.values()),
            "CONFLICTING_REVIEW" if any(len(values) > 1 for values in selected.values()) else "MISSING_REGISTERED_GLOBAL_ROOT",
            task_id + ": review/context/issuance must each be registered exactly once")
    return {key: values[0] for key, values in selected.items()}

def _verify_owner(reader, owner, task_id, roots, plan_path):
    if task_id == "W07":
        return _w07_profile(reader).verify_owner(_profile_api(), reader, owner, roots, plan_path)
    if task_id == "W09":
        return _w09_profile(reader).verify_owner(_profile_api(), reader, owner, roots, plan_path)
    require(task_id == "W04", "UNSUPPORTED_PROTOCOL", "No verified evidence profile is implemented for " + task_id)
    context, _ = _currentness(reader, roots["context"])
    require(not reader.read(roots["review"]).get("supersedes_review_refs"), "SUPERSESSION_NOT_SUPPORTED", task_id)
    review = reader.read(roots["review"])
    issuance = reader.read(roots["issuance"])
    require(stamp(review["issued_at"], "review issued_at") <= stamp(issuance["observed_at"], "root observed_at")
            <= stamp(owner.get("accepted_at"), "owner accepted_at"), "REGISTERED_TIME_ORDER", task_id)
    baseline = reader.ref(review["acceptance_baseline_ref"])
    require(baseline.name == "acceptance.json" and sha256(baseline) == FROZEN_HASHES["acceptance.json"], "FROZEN_BASELINE", task_id)
    result = _check_w04_profile(reader.repo, reader.repo / "execution/v2.4/step_state.json", baseline.parent.parent,
                                roots["context"], roots["review"], roots["issuance"], phase="registered")
    require(result["formal_accepted_count"] == 3 and set(result["eligible_owned_cases"]) == set(CASE_IDS), "PROFILE_RESULT", task_id)
    for absolute, digest in result["input_hashes"].items():
        path = Path(absolute)
        if path in reader.read_hashes:
            require(reader.read_hashes[path] == digest, "INPUT_CHANGED_DURING_READ", absolute)
        reader.read_hashes[path] = digest
    return context

def recheck_inputs(snapshot):
    """CAS dependency check; no product commands or authoritative input writes."""
    try:
        for name, digest in snapshot["files"].items():
            path = Path(name)
            require(path.is_file() and sha256(path) == digest, "INPUT_CHANGED_DURING_READ", name)
        for item in snapshot.get("audit_ranges", []):
            _audit_range(item)
        for inventory in snapshot.get("inventories", []):
            repo = Path(inventory["repo"])
            check_reader = Reader(repo)
            if inventory.get("kind") == "owned_raw":
                current = _owned_inventory(check_reader, inventory["directory"], inventory["members"])
                require(current == inventory, "OWNED_INVENTORY_CHANGED", inventory["directory"])
            else:
                coverage(check_reader, inventory["coverage"], [{"path": name} for name in inventory["paths"]])
    except (InvalidEvidence, OSError, ValueError) as exc:
        return {"status": "INVALID", "reason": str(exc)}
    return {"status": "PASS"}

def derive_formal_cases(repo_root, state_path, plan_path):
    """Derive all frozen owners from canonical registration, preserving history."""
    result = {"schema": "researchos.formal-case-index.v1", "scope": "DERIVED_READ_ONLY_CURRENT_FORMAL_STATUS",
              "integrity": "PASS", "required_formal_cases": 42, "accepted_case_ids": [], "formal_cases_accepted": 0,
              "cases": [], "owners": [], "reasons": [], "input_hashes": {}, "catalog_hashes": dict(FROZEN_HASHES),
              "product_business_acceptance_created": False, "dependency_snapshot": {"files": {}, "inventories": [], "audit_ranges": []}}
    reader = None
    try:
        reader = Reader(repo_root)
        cases, tasks, parents, owned, planned = _catalog(reader, plan_path)
        rows = _canonical_state(reader, state_path, planned)
        _w07_profile(reader)  # Trusted modules participate in every dependency/CAS snapshot.
        _w09_profile(reader)
    except (InvalidEvidence, OSError, ValueError, KeyError, TypeError, StopIteration) as exc:
        result.update(integrity="INVALID", reasons=[{"code": getattr(exc, "code", "GLOBAL_INPUT_INVALID"), "detail": str(exc)}])
        if reader is not None:
            result["input_hashes"] = {str(path): digest for path, digest in reader.read_hashes.items()}
            result["dependency_snapshot"]["files"] = dict(result["input_hashes"])
        return result
    for task_id in tasks:
        row = rows.get(parents[task_id]["id"], {})
        owner = {"task_id": task_id, "step_id": parents[task_id]["id"], "parent_status": row.get("status", "NOT_STARTED"),
                 "owned_case_ids": owned[task_id], "accepted_case_ids": [], "integrity": "NOT_RUN", "reasons": []}
        if not owned[task_id]:
            owner["integrity"] = "EMPTY_OWNER"
        elif row.get("status") != "ACCEPTED":
            owner["integrity"] = "NOT_RUN" if row.get("status", "NOT_STARTED") == "NOT_STARTED" else "PENDING_OWNER_ACCEPTANCE"
        else:
            try:
                require(task_id in {"W04", "W07", "W09"}, "UNSUPPORTED_PROTOCOL", "Evidence profile has not been independently implemented for " + task_id)
                roots = _registered_roots(reader, row, task_id)
                context = _verify_owner(reader, row, task_id, roots, plan_path)
                owner.update(integrity="VALID_ACCEPTED", accepted_case_ids=list(owned[task_id]))
                result["dependency_snapshot"]["inventories"].append({"repo": str(reader.repo), "coverage": context["source_coverage"],
                                                                      "paths": [ref["path"] for ref in context["version_vector"]["source_files"]]})
                if task_id == "W09":
                    result["dependency_snapshot"]["inventories"].extend(context["_verified_owned_inventories"])
                    result["dependency_snapshot"]["audit_ranges"].extend(context["_verified_audit_ranges"])
            except (InvalidEvidence, OSError, ValueError, KeyError, TypeError, StopIteration) as exc:
                code = getattr(exc, "code", "OWNER_EVIDENCE_INVALID")
                owner["integrity"] = "NEEDS_REVALIDATION" if code in {"NEEDS_REVALIDATION", "TOOL_CHANGED", "SOURCE_COVERAGE"} else (
                    "PARTIAL" if code in {"MISSING_REGISTERED_GLOBAL_ROOT", "MISSING_FIELD", "DEPENDENCY", "UNREGISTERED_REFERENCE"} else "INVALID")
                owner["reasons"] = [{"code": code, "detail": str(exc)}]
                result["reasons"].append({"task_id": task_id, **owner["reasons"][0]})
        result["owners"].append(owner)
        for cid in owned[task_id]:
            result["cases"].append({"case_id": cid, "final_owner_task": task_id, "required_mode": cases[cid]["mode"],
                                    "status": owner["integrity"], "reasons": owner["reasons"]})
        result["accepted_case_ids"].extend(owner["accepted_case_ids"])
    try:
        for item in result["dependency_snapshot"]["audit_ranges"]:
            _audit_range(item)
        for inventory in result["dependency_snapshot"]["inventories"]:
            if inventory.get("kind") == "owned_raw":
                require(_owned_inventory(reader, inventory["directory"], inventory["members"]) == inventory,
                        "OWNED_INVENTORY_CHANGED", inventory["directory"])
        reader.finish()
    except (InvalidEvidence, OSError) as exc:
        result.update(integrity="INVALID", accepted_case_ids=[], reasons=result["reasons"] + [{"code": "INPUT_CHANGED_DURING_READ", "detail": str(exc)}])
        for owner in result["owners"]:
            owner["accepted_case_ids"] = []
            if owner["integrity"] == "VALID_ACCEPTED":
                owner["integrity"] = "NEEDS_REVALIDATION"
        for case in result["cases"]:
            if case["status"] == "VALID_ACCEPTED":
                case["status"] = "NEEDS_REVALIDATION"
    if result["integrity"] == "PASS" and result["reasons"]:
        result["integrity"] = "PARTIAL"
    result["accepted_case_ids"] = sorted(set(result["accepted_case_ids"]))
    result["formal_cases_accepted"] = len(result["accepted_case_ids"])
    result["input_hashes"] = {str(path): digest for path, digest in reader.read_hashes.items()}
    result["dependency_snapshot"]["files"] = dict(result["input_hashes"])
    return result

def main():
    if len(sys.argv) != 2 or sys.argv[1] not in {"test.retrieval", "test.research.fixture", "test.security"}:
        return _failure("INVALID_COMMAND_KEY")
    route = (sys.argv[1], os.getenv("RESEARCHOS_TASK_ID", ""),
             os.getenv("RESEARCHOS_CHECK_ID", ""), os.getenv("RESEARCHOS_CASE_ID", ""))
    if route not in NATIVE and route not in PRESERVED:
        return _failure("UNBOUND_SELECTOR_TUPLE")
    if not (ROOT / "execution/toolchains/locked.json").is_file():
        return _failure("WRONG_REPOSITORY_CWD")
    if route in PRESERVED:
        go = os.getenv("RESEARCHOS_GO", "")
        if route[1] == "W09":
            argv = [sys.executable, "-X", "utf8", str(ROOT / "tests/evidence/check/main.py")]
        elif route[1] == "W08":
            if not go: return _failure("MISSING_LOCKED_GO")
            argv = [go, "run", "./tests/research/check"]
        else:
            if not go: return _failure("MISSING_LOCKED_GO")
            argv = [go, "run", "./tests/security/check"]
        child = subprocess.run(argv, cwd=ROOT, env=os.environ.copy(),
                               stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                               check=False, shell=False)
        sys.stderr.buffer.write(child.stderr)
        sys.stdout.buffer.write(child.stdout)
        return child.returncode
    try:
        source, report, tool = _pinned_native_report()
        pins, report, native = _native_exact(source, route)
        owned = _owned_exact(source, report, route)
        mode = _mode_review(source, report, route, owned, native)
        if mode.get("formal_authority") is not False:
            raise ValueError("MODE_REVIEW_MUST_NOT_SELF_ACCEPT")
    except (OSError, ValueError, KeyError, TypeError, IndexError) as exc:
        return _failure("SEALED_NATIVE_OR_POSTRUN_MODE_OPEN", type(exc).__name__)
    print(json.dumps({"status": "PASS", "assertion_ids": list(FORMAL[route]),
                      "assertions": len(FORMAL[route]), "task_id": "W09",
                      "check_id": route[2] or None, "case_id": route[3] or None,
                      "native_assertion_ids": list(NATIVE[route]),
                      "source_pins": pins, "owned_export_member_count": len(owned["members"]),
                      "native_tool_run_ref": os.getenv("RESEARCHOS_W09_TOOL_RUN_REF"),
                      "mode_evidence": mode,
                      "formal_acceptance": "PENDING_INDEPENDENT_VERIFIER"}, ensure_ascii=False))
    return 0

def execute(key, selectors=None, *, root=ROOT, spec='auto'):
    selectors = selectors or {}
    invocation = str(uuid.uuid4())
    output = within(root, 'execution/invocations') / invocation
    output.mkdir(parents=True, exist_ok=False)
    receipt = dict(invocation_id=invocation, command_key=key, started_at=now(),
                   status='ERROR', exit_code=1, child_exit_code=None, assertion_ids=[],
                   selectors=selectors, scope='CONSTRUCTION_CHECK_NOT_PRODUCT_ACCEPTANCE',
                   stdout_sanitized=True, stderr_sanitized=True)
    stdout, stderr = b'', b''
    secrets = [v.encode() for k, v in os.environ.items()
               if re.search(r'(TOKEN|SECRET|PASSWORD|API_KEY)', k, re.I) and len(v) >= 4]

    def fail(status, code=1):
        receipt.update(status=status, exit_code=code)

    try:
        registry_path, registry_spec = resolve_registry(root, key, spec)
        registry = read(registry_path)
        receipt['registry_spec'] = registry_spec
        receipt['registered_command_revision'] = sha(registry_path)
        entry = registry['commands'].get(key)
        if not entry or entry['state'] != 'BOUND':
            fail('NOT_IMPLEMENTED', 3)
        elif platform.system() not in entry['platforms']:
            fail('UNSUPPORTED_PLATFORM', 4)
        elif any(value and '*' not in entry.get('selectors', {}).get(name, [])
                 and value not in entry.get('selectors', {}).get(name, [])
                 for name, value in selectors.items()):
            fail('NOT_IMPLEMENTED', 3)
        elif any(not os.environ.get(name) for name in entry['required_env']):
            receipt['missing_environment_names'] = [n for n in entry['required_env'] if not os.environ.get(n)]
            fail('MISSING_CREDENTIAL_OR_ENVIRONMENT', 5)
        else:
            locked_path = root / 'execution/toolchains/locked.json'
            locked = read(locked_path)
            receipt['toolchain_revision'] = sha(locked_path)
            receipt['dispatcher_sha256'] = sha(Path(__file__))
            receipt['input_versions'] = []
            for argument in entry['argv']:
                path = (root / argument).resolve()
                if path.is_relative_to(root.resolve()) and path.is_file():
                    receipt['input_versions'].append({'path': path.relative_to(root).as_posix(), 'sha256': sha(path)})
            if 'git' in locked['tools']:
                git = locked['tools']['git']
                if sha(Path(git['path'])) != git['sha256']:
                    raise ValueError('GIT_TOOLCHAIN_CHANGED')
                revision = subprocess.run([git['path'], 'rev-parse', 'HEAD'], cwd=root,
                                          capture_output=True, text=True, timeout=10, check=True)
                receipt['code_revision'] = revision.stdout.strip()
            tool = locked['tools'][entry['executable_tool']]
            executable = Path(tool['path'])
            if not executable.is_absolute() or not executable.is_file():
                fail('MISSING_EXECUTABLE', 6)
            elif sha(executable) != tool['sha256']:
                fail('TOOLCHAIN_CHANGED', 6)
            else:
                argv = [str(executable), *entry['argv']]
                if any(secret in arg.encode() for secret in secrets for arg in argv):
                    fail('SECRET_IN_ARGUMENTS', 7)
                else:
                    cwd = within(root, entry['cwd'])
                    env = {name: os.environ[name] for name in entry['allowed_env'] if name in os.environ}
                    env.update(entry.get('fixed_env', {}))
                    env.update({'RESEARCHOS_' + name.upper(): value for name, value in selectors.items() if value})
                    for name, tool_name in entry.get('tool_env', {}).items():
                        selected = locked['tools'][tool_name]
                        path = Path(selected['path'])
                        if not path.is_file() or sha(path) != selected['sha256']:
                            raise ValueError('TOOLCHAIN_CHANGED')
                        env[name] = str(path)
                    receipt.update(argv=argv, cwd=str(cwd), environment_names=sorted(env),
                                   timeout_seconds=entry['timeout_seconds'])
                    process = subprocess.Popen(argv, cwd=cwd, env=env, stdout=subprocess.PIPE,
                                               stderr=subprocess.PIPE, shell=False)
                    receipt['pid'] = process.pid
                    try:
                        stdout, stderr = process.communicate(timeout=entry['timeout_seconds'])
                    except subprocess.TimeoutExpired:
                        parent_exited = process.poll() is not None
                        if parent_exited:
                            receipt['timeout_cleanup_unconfirmed'] = True
                        elif os.name == 'nt':
                            killer = Path(os.environ['SystemRoot']) / 'System32/taskkill.exe'
                            try:
                                stopped = subprocess.run([str(killer), '/PID', str(process.pid), '/T', '/F'], capture_output=True, timeout=5)
                                receipt['timeout_cleanup_exit_code'] = stopped.returncode
                            except subprocess.TimeoutExpired:
                                receipt['timeout_cleanup_unconfirmed'] = True
                        else:
                            process.kill()
                        if not parent_exited:
                            try:
                                stdout, stderr = process.communicate(timeout=2)
                            except subprocess.TimeoutExpired:
                                process.kill()
                                # A pipe held by an unconfirmed descendant cannot be closed
                                # synchronously: communicate's reader owns its lock.
                                receipt['timeout_cleanup_unconfirmed'] = True
                        fail('TIMEOUT', 8)
                    receipt['child_exit_code'] = process.returncode
                    if receipt['status'] != 'TIMEOUT':
                        report = None
                        try:
                            text = stdout.decode('utf-8')
                            try:
                                report = decode(text)
                            except json.JSONDecodeError:
                                report = decode(text.strip().splitlines()[-1])
                        except (ValueError, IndexError):
                            pass
                        ids = report.get(entry.get('assertion_field', 'assertion_ids'), []) if isinstance(report, dict) else []
                        valid_ids = isinstance(ids, list) and all(isinstance(x, str) and x for x in ids) and len(set(ids)) == len(ids)
                        if valid_ids:
                            receipt['assertion_ids'] = ids
                        if process.returncode != 0:
                            fail('COMMAND_FAILED', 1)
                        elif not isinstance(report, dict):
                            fail('INVALID_ASSERTION_REPORT', 9)
                        elif not isinstance(ids, list) or not ids:
                            fail('NOT_IMPLEMENTED', 3)
                        elif not valid_ids:
                            fail('INVALID_ASSERTION_REPORT', 9)
                        elif report.get('status') != 'PASS':
                            fail('CHECK_FAILED', 1)
                        elif 'assertions' in report and report['assertions'] != len(ids):
                            fail('INVALID_ASSERTION_REPORT', 9)
                        else:
                            receipt.update(status='PASS', exit_code=0, reported_scope=report.get('scope'))
    except (OSError, ValueError, KeyError, TypeError, IndexError, subprocess.SubprocessError) as exc:
        # The exception text can contain credentials from child output; never persist it.
        fail('DISPATCH_ERROR', 10)
        receipt['error_type'] = type(exc).__name__
    variants = set(secrets)
    for secret in secrets:
        variants.add(json.dumps(secret.decode(), ensure_ascii=True)[1:-1].encode())
        variants.add(json.dumps(secret.decode(), ensure_ascii=False)[1:-1].encode())
    for secret in sorted(variants, key=len, reverse=True):
        stdout = stdout.replace(secret, b'[REDACTED]')
        stderr = stderr.replace(secret, b'[REDACTED]')
    # Child assertion labels/scope are untrusted too.
    def sanitize(value):
        if isinstance(value, str):
            for secret in secrets:
                value = value.replace(secret.decode(), '[REDACTED]')
            return value
        if isinstance(value, list):
            return [sanitize(item) for item in value]
        if isinstance(value, dict):
            return {sanitize(key): sanitize(item) for key, item in value.items()}
        return value
    receipt = sanitize(receipt)
    for name, data in [('stdout', stdout), ('stderr', stderr)]:
        path = output / (name + '.txt')
        path.write_bytes(data)
        receipt[name] = {'path': path.relative_to(root).as_posix(), 'sha256': sha(path)}
    receipt['ended_at'] = now()
    receipt_path = output / 'receipt.json'
    receipt_path.write_text(json.dumps(receipt, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    return receipt, receipt_path
